head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====
// footer1 Footer Cell 의 실제 적용 font-size 를 읽어온다
scwin.getFooter1FontSize = function () {
    var objGrid = $p.getComponentById("target1");
    var objCell = objGrid.render.querySelector("[id$='_footer1']");

    if (!objCell) {
        return "Footer Cell 없음";
    }
    return window.getComputedStyle(objCell).fontSize;
};

// cellInfo 로 Footer Cell 을 지정해 font-size 를 적용하고 결과를 출력
scwin.applyFooterStyle = function (objCellInfo, strCellInfoLabel) {
    var objGrid = $p.getComponentById("target1");

    objGrid.setFooterStyle(objCellInfo, "font-size", "20px");
    scwin.setReturnValue("[호출] setFooterStyle(" + strCellInfoLabel + ", font-size, 20px)");

    scwin.setReturnValue("getFooterStyle(" + strCellInfoLabel + ", font-size) : "
        + objGrid.getFooterStyle(objCellInfo, "font-size"));
    scwin.setReturnValue("footer1 Footer Cell 실제 font-size : " + scwin.getFooter1FontSize());
};

scwin.btn_byIndex_onclick = function (e) {
    scwin.applyFooterStyle(0, "0");
};

scwin.btn_byId_onclick = function (e) {
    scwin.applyFooterStyle("footer1", "footer1");
};
